# Writes src\QuasarPad\Assets\QuasarPad.ico from embedded base64 (run once after clone)
$ErrorActionPreference = "Stop"
$repo = Split-Path $PSScriptRoot -Parent
if (-not (Test-Path (Join-Path $repo "src\QuasarPad"))) { $repo = Get-Location }
$dir = Join-Path $repo "src\QuasarPad\Assets"
New-Item -ItemType Directory -Force -Path $dir | Out-Null
# Tiny multi-size icon (16/32/48) — regenerate with full logo later if needed
$b64 = ""
Write-Host "Icon script placeholder - use Assets from build machine. Prefer copying QuasarPad.ico manually."
